function MacroBalanceChart({ macros, totalFoodGrams, dayLabel, colors }: { macros: NutritionMacros; totalFoodGrams: number; dayLabel: string; colors: ReturnType<typeof useColors> }) {
  const { t } = useLanguage();
  const radius = 52; const circumference = 2 * Math.PI * radius;
  const segments = [
    { key: "protein", label: t("nutrition.macro.protein"), shortLabel: t("nutrition.macro.proteinShort"), grams: macros.protein, color: colors.primary },
    { key: "fat", label: t("nutrition.macro.fat"), shortLabel: t("nutrition.macro.fatShort"), grams: macros.fat, color: "#2F5FC4" },
    { key: "carbs", label: t("nutrition.macro.carbs"), shortLabel: t("nutrition.macro.carbsShort"), grams: macros.carbs, color: "#E6A52D" },
  ];
  const total = segments.reduce((sum, segment) => sum + segment.grams, 0);
  let consumed = 0;
  return <View style={[styles.macroChart, { backgroundColor: colors.surface, borderColor: colors.border }]}>
    <View style={styles.macroChartHeader}><View><Text style={[styles.macroChartTitle, { color: colors.foreground }]}>{t("nutrition.chart.title")}</Text><Text style={[styles.macroChartHint, { color: colors.muted }]}>{t("nutrition.chart.hint", { day: dayLabel })}</Text></View><Text style={[styles.macroChartTotal, { color: colors.primary }]}>{t("nutrition.chart.totalValue", { grams: totalFoodGrams })}</Text></View>
    <View style={styles.macroChartBody}>
      <View style={styles.macroDonutWrap}>
        <Svg width={142} height={142} viewBox="0 0 142 142" accessibilityLabel={t("nutrition.chart.a11y")}>
          <Circle cx="71" cy="71" r={radius} fill="none" stroke={colors.border} strokeWidth="20" />
          {total > 0 && segments.map((segment) => { const length = (segment.grams / total) * circumference; const offset = -consumed; consumed += length; return <Circle key={segment.key} cx="71" cy="71" r={radius} fill="none" stroke={segment.color} strokeWidth="20" strokeDasharray={`${Math.max(0, length - 2.4)} ${circumference - Math.max(0, length - 2.4)}`} strokeDashoffset={offset} strokeLinecap="round" transform="rotate(-90 71 71)" />; })}
          <Circle cx="71" cy="71" r="33" fill={colors.background} />
          <SvgText x="71" y="69" textAnchor="middle" fill={colors.foreground} fontSize="23" fontWeight="900">{total}</SvgText>
          <SvgText x="71" y="83" textAnchor="middle" fill={colors.muted} fontSize="8" fontWeight="900" letterSpacing="1">{t("nutrition.chart.gramsCaption")}</SvgText>
        </Svg>
      </View>
      <View style={styles.macroLegend}>{segments.map((segment) => { const percentage = total ? Math.round((segment.grams / total) * 100) : 0; return <View key={segment.key} style={styles.macroLegendItem}><View style={[styles.macroLegendDot, { backgroundColor: segment.color }]} /><View style={{ flex: 1 }}><Text style={[styles.macroLegendLabel, { color: colors.muted }]}>{segment.label}</Text><Text style={[styles.macroLegendValue, { color: colors.foreground }]}>{t("nutrition.macro.gramsValue", { value: segment.grams })}</Text></View><Text style={[styles.macroLegendPercent, { color: segment.color }]}>{percentage}%</Text></View>; })}</View>
    </View>
  </View>;
}

